	"auth.help":
		"Usage:\n  {p0} auth print-api-key [--provider <provider>] [--model <model>]\n  {p0} auth print-bearer-token [--provider <provider>] [--model <model>] [--min-expiry <duration>]\n  {p0} auth check [--provider <provider>] [--model <model>] [--json] [--credentials] [--no-refresh]\n\nAuth commands require at least one of --provider or --model. Checks refresh expired OAuth credentials by default; --no-refresh prevents this. --credentials emits the credential, or includes it in JSON output.",
	"package_help.config":
		"{p0}\n  {p1}\n\nOpen the resource configuration TUI to enable or disable package resources.\nWithout -l, starts in global settings (~/{p2}/agent/settings.json).\nPress Tab in the TUI to switch between global and project-local modes.\n\nOptions:\n  -l, --local       Edit project overrides ({p2}/settings.json)\n  -a, --approve     Trust project-local files for this command with -l\n  -na, --no-approve Ignore project-local files for this command with -l\n",
	"package_help.install":
		"{p0}\n  {p1}\n\nInstall a package and add it to settings.\n\nOptions:\n  -l, --local       Install project-locally ({p2}/settings.json)\n  -a, --approve     Trust project-local files for this command\n  -na, --no-approve Ignore project-local files for this command\n\nExamples:\n  {p3} install npm:@foo/bar\n  {p3} install git:github.com/user/repo\n  {p3} install git:git@github.com:user/repo\n  {p3} install https://github.com/user/repo\n  {p3} install ssh://git@github.com/user/repo\n  {p3} install ./local/path\n",
	"package_help.remove":
		"{p0}\n  {p1}\n\nRemove a package and its source from settings.\nAlias: {p2} uninstall <source> [-l]\n\nOptions:\n  -l, --local       Remove from project settings ({p3}/settings.json)\n  -a, --approve     Trust project-local files for this command\n  -na, --no-approve Ignore project-local files for this command\n\nExamples:\n  {p2} remove npm:@foo/bar\n  {p2} uninstall npm:@foo/bar\n",
	"package_help.update":
		"{p0}\n  {p1}\n\nUpdate pi, installed packages, or model catalogs.\n\nOptions:\n  --self                  Update pi only (default when no target is given)\n  --extensions            Update installed packages only\n  --models                Refresh model catalogs only\n  --all                   Update pi and installed packages\n  --extension <source>    Update one package only\n  -a, --approve           Trust project-local files for this command\n  -na, --no-approve       Ignore project-local files for this command\n  --force                 Reinstall pi even if the current version is latest\n\nShort forms:\n  {p2} update                Update pi only\n  {p2} update --all          Update pi and all extensions\n  {p2} update --models       Refresh model catalogs only\n  {p2} update <source>       Update one package\n  {p2} update pi             Update pi only (self works as alias to pi)\n",
	"package_help.list":
		"{p0}\n  {p1}\n\nList installed packages from user and project settings.\n\nOptions:\n  -a, --approve      Trust project-local files for this command\n  -na, --no-approve  Ignore project-local files for this command\n",
